package com.bank.security;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;

// Demonstrates salted, one-way hashing. In production use Spring Security's
// BCryptPasswordEncoder — never SHA alone. This shows the salt+hash idea.
class PasswordHasher {

    String hash(String rawPassword) {
        byte[] salt = new byte[16];
        new SecureRandom().nextBytes(salt);
        String saltB64 = Base64.getEncoder().encodeToString(salt);
        return saltB64 + ":" + digest(rawPassword, saltB64);
    }

    boolean matches(String rawPassword, String stored) {
        String[] parts = stored.split(":");
        String saltB64 = parts[0];
        return digest(rawPassword, saltB64).equals(parts[1]);
    }

    private String digest(String raw, String saltB64) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(saltB64.getBytes(StandardCharsets.UTF_8));
            byte[] out = md.digest(raw.getBytes(StandardCharsets.UTF_8));
            return Base64.getEncoder().encodeToString(out);
        } catch (Exception e) {
            throw new IllegalStateException("Hashing failed", e);
        }
    }
}
