package com.bank.security;

import java.time.Instant;
import java.util.Base64;

// A readable stand-in for a JWT. It carries claims (subject + expiry) and a
// signature. In production use a real JWT library (jjwt / Nimbus) with RS256.
class TokenService {
    private final String secret;   // represents the signing key

    TokenService(String secret) { this.secret = secret; }

    String issue(String username, long ttlSeconds) {
        long exp = Instant.now().getEpochSecond() + ttlSeconds;
        String payload = username + "|" + exp;
        String signature = sign(payload);
        return Base64.getEncoder().encodeToString((payload + "|" + signature).getBytes());
    }

    // Returns the username if valid, else throws. Validates signature + expiry.
    String validate(String token) {
        String decoded = new String(Base64.getDecoder().decode(token));
        String[] parts = decoded.split("\\|");
        String payload = parts[0] + "|" + parts[1];
        String signature = parts[2];
        if (!sign(payload).equals(signature)) {
            throw new SecurityException("Invalid token signature");
        }
        long exp = Long.parseLong(parts[1]);
        if (Instant.now().getEpochSecond() > exp) {
            throw new SecurityException("Token expired");
        }
        return parts[0];  // the authenticated username (the claim)
    }

    private String sign(String payload) {
        return Integer.toHexString((payload + secret).hashCode());
    }
}
