package com.bank.security;

import java.util.Map;
import java.util.logging.Logger;

// Enforces that the authenticated caller can only read their OWN account.
// This is the defense against IDOR.
class AccountSecurityService {
    private static final Logger log = Logger.getLogger(AccountSecurityService.class.getName());

    private final TokenService tokenService;
    private final Map<String, Account> accountsById;

    AccountSecurityService(TokenService tokenService, Map<String, Account> accountsById) {
        this.tokenService = tokenService;
        this.accountsById = accountsById;
    }

    Account getAccount(String bearerToken, String requestedAccountId) {
        String caller = tokenService.validate(bearerToken);   // verify + get username
        Account account = accountsById.get(requestedAccountId);
        if (account == null) {
            throw new IllegalArgumentException("Account not found: " + requestedAccountId);
        }
        // IDOR defense: scope to owner. Never return another user's account.
        if (!account.getOwnerUsername().equals(caller)) {
            log.warning(() -> "DENIED: " + caller + " tried to access " + requestedAccountId);
            throw new SecurityException("Access denied to " + requestedAccountId);
        }
        log.info(() -> "GRANTED: " + caller + " accessed " + requestedAccountId);
        return account;
    }
}
