package com.bank.security;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

public class SecurityDemo {
    private static final Logger log = Logger.getLogger(SecurityDemo.class.getName());

    public static void main(String[] args) {
        PasswordHasher hasher = new PasswordHasher();
        String rajeshStored = hasher.hash("rajesh@Secure1");
        log.info(() -> "Stored password hash (never the raw value): " + rajeshStored);
        log.info(() -> "Login check correct password: " + hasher.matches("rajesh@Secure1", rajeshStored));
        log.info(() -> "Login check wrong password: " + hasher.matches("guess123", rajeshStored));

        Map<String, Account> accounts = new LinkedHashMap<>();
        accounts.put("SAV2001", new Account("SAV2001", "rajesh", "Rajesh", new BigDecimal("1000000")));
        accounts.put("CUR3001", new Account("CUR3001", "priya", "Priya", new BigDecimal("250000")));

        TokenService tokens = new TokenService("bank-signing-key");
        AccountSecurityService service = new AccountSecurityService(tokens, accounts);

        String rajeshToken = tokens.issue("rajesh", 900);  // 15-minute access token

        // Rajesh reads his own account — allowed.
        Account own = service.getAccount(rajeshToken, "SAV2001");
        log.info(() -> "Rajesh sees balance Rs." + own.getBalance());

        // Rajesh tries to read Priya's account — IDOR attempt, denied.
        try {
            service.getAccount(rajeshToken, "CUR3001");
        } catch (SecurityException ex) {
            log.severe("IDOR blocked: " + ex.getMessage());
        }
    }
}
